def countDeletionSpots(s):
    n = len(s)

    def run(i):
        a = i
        while a > 0 and s[a - 1] == s[i]:
            a -= 1
        b = i
        while b < n - 1 and s[b + 1] == s[i]:
            b += 1
        return b - a + 1

    def pal(i, j):
        while i < j:
            if s[i] != s[j]:
                return False
            i += 1
            j -= 1
        return True

    l, r = 0, n - 1
    while l < r and s[l] == s[r]:
        l += 1
        r -= 1
    if l >= r:
        return run(n // 2)
    total = 0
    if pal(l + 1, r):
        total += run(l)
    if pal(l, r - 1):
        total += run(r)
    return total
